-- ============================================================
-- V10: 区域管理（rx_region 行政区划数据）+ 日历（rx_calendar_event）+ 工具分组菜单
-- 区划数据来源：民政部2024年8月县及县以上行政区划代码（旧项目 update_regions*.sql，23 省）
-- 菜单行仅在菜单表已有数据时执行（全新库由 DataInitializer 种子写入，避免双写）
-- ============================================================

CREATE TABLE rx_region (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(12) NOT NULL COMMENT '行政区划代码',
    name VARCHAR(64) NOT NULL COMMENT '名称',
    level TINYINT NOT NULL COMMENT '1=省 2=市 3=区/县',
    parent_code VARCHAR(12) NOT NULL DEFAULT '' COMMENT '上级代码（空=省）',
    pinyin VARCHAR(128) NULL COMMENT '拼音',
    abbreviation VARCHAR(32) NULL COMMENT '简称',
    longitude DECIMAL(10,6) NULL COMMENT '经度',
    latitude DECIMAL(10,6) NULL COMMENT '纬度',
    sort INT NOT NULL DEFAULT 0 COMMENT '排序',
    status TINYINT NOT NULL DEFAULT 1 COMMENT '0=禁用 1=启用',
    created_time DATETIME NULL,
    updated_time DATETIME NULL,
    UNIQUE KEY uk_region_code (code),
    INDEX idx_region_parent (parent_code),
    INDEX idx_region_level (level)
) COMMENT '中国行政区划';

CREATE TABLE rx_calendar_event (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT NOT NULL COMMENT '创建人（rx_user.id）',
    title VARCHAR(128) NOT NULL COMMENT '标题',
    description VARCHAR(1000) NULL COMMENT '描述',
    event_date DATE NOT NULL COMMENT '日期',
    start_time TIME NULL COMMENT '开始时间',
    end_time TIME NULL COMMENT '结束时间',
    event_type VARCHAR(16) NOT NULL DEFAULT 'other' COMMENT 'meeting/task/reminder/other',
    priority TINYINT NOT NULL DEFAULT 1 COMMENT '1=低 2=中 3=高',
    color VARCHAR(16) NULL COMMENT '标记色',
    is_all_day TINYINT NOT NULL DEFAULT 1 COMMENT '1=全天 0=按时间',
    status TINYINT NOT NULL DEFAULT 1 COMMENT '1=正常 0=已取消',
    created_time DATETIME NULL,
    updated_time DATETIME NULL,
    INDEX idx_cal_user_date (user_id, event_date)
) COMMENT '日历事件';

-- ---- 工具分组菜单（groupTools）+ 区域 + 日历 ----
-- 仅当菜单表已有数据时插入（旧库场景）；全新库由 DataInitializer 负责
SELECT NULL, '工具', 1, 'groupTools', '/group-tools', NULL, NULL, 'Tools', 7, 1, 1, 0, NOW(), NOW()
WHERE EXISTS (SELECT 1 FROM rx_menu) AND NOT EXISTS (SELECT 1 FROM rx_menu WHERE title = 'groupTools');

SELECT p.id, '区域管理', 2, 'region', '/region', 'views/tool/region/index.vue', 'REGION_VIEW', 'Location', 1, 1, 1, 0, NOW(), NOW()
FROM rx_menu p
WHERE p.title = 'groupTools' AND EXISTS (SELECT 1 FROM rx_menu) AND NOT EXISTS (SELECT 1 FROM rx_menu WHERE title = 'region');

SELECT p.id, '日历', 2, 'calendar', '/calendar', 'views/calendar/index.vue', 'CALENDAR_VIEW', 'Calendar', 2, 1, 1, 0, NOW(), NOW()
FROM rx_menu p
WHERE p.title = 'groupTools' AND EXISTS (SELECT 1 FROM rx_menu) AND NOT EXISTS (SELECT 1 FROM rx_menu WHERE title = 'calendar');

